#include <vector>
#include <queue>

using namespace std;

class Solution {
public:
    vector<int> sumOfDistancesInTree(int n, vector<vector<int>>& edges) {
        if (n <= 1) return {0};

        vector<vector<int>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }

        vector<int> parent(n, -1);
        vector<int> order;
        order.reserve(n);
        vector<bool> visited(n, false);
        visited[0] = true;
        queue<int> q;
        q.push(0);

        while (!q.empty()) {
            int u = q.front();
            q.pop();
            order.push_back(u);
            for (int v : adj[u]) {
                if (!visited[v]) {
                    visited[v] = true;
                    parent[v] = u;
                    q.push(v);
                }
            }
        }

        vector<int> count(n, 1);
        vector<int> ans(n, 0);

        for (int i = n - 1; i > 0; --i) {
            int u = order[i];
            int p = parent[u];
            count[p] += count[u];
            ans[p] += ans[u] + count[u];
        }

        for (int i = 1; i < n; ++i) {
            int u = order[i];
            int p = parent[u];
            ans[u] = ans[p] - count[u] + (n - count[u]);
        }

        return ans;
    }
};

import java.util.List;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Queue;
import java.util.ArrayDeque;

class Solution {
    public int[] sumOfDistancesInTree(int n, int[][] edges) {
        if (n <= 1) return new int[]{0};

        List<List<Integer>> adj = new ArrayList<>(n);
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }

        int[] parent = new int[n];
        Arrays.fill(parent, -1);
        int[] order = new int[n];
        int orderIdx = 0;
        boolean[] visited = new boolean[n];
        visited[0] = true;
        Queue<Integer> queue = new ArrayDeque<>();
        queue.offer(0);

        while (!queue.isEmpty()) {
            int u = queue.poll();
            order[orderIdx++] = u;
            for (int v : adj.get(u)) {
                if (!visited[v]) {
                    visited[v] = true;
                    parent[v] = u;
                    queue.offer(v);
                }
            }
        }

        int[] count = new int[n];
        Arrays.fill(count, 1);
        int[] ans = new int[n];

        for (int i = n - 1; i > 0; i--) {
            int u = order[i];
            int p = parent[u];
            count[p] += count[u];
            ans[p] += ans[u] + count[u];
        }

        for (int i = 1; i < n; i++) {
            int u = order[i];
            int p = parent[u];
            ans[u] = ans[p] - count[u] + (n - count[u]);
        }

        return ans;
    }
}

/**
 * @param {number} n
 * @param {number[][]} edges
 * @return {number[]}
 */
var sumOfDistancesInTree = function(n, edges) {
    if (n <= 1) return [0];

    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }

    const parent = new Int32Array(n).fill(-1);
    const order = [];
    const visited = new Uint8Array(n);
    visited[0] = 1;
    const queue = [0];

    let head = 0;
    while (head < queue.length) {
        const u = queue[head++];
        order.push(u);
        for (const v of adj[u]) {
            if (!visited[v]) {
                visited[v] = 1;
                parent[v] = u;
                queue.push(v);
            }
        }
    }

    const count = new Int32Array(n).fill(1);
    const ans = new Int32Array(n);

    for (let i = n - 1; i > 0; i--) {
        const u = order[i];
        const p = parent[u];
        count[p] += count[u];
        ans[p] += ans[u] + count[u];
    }

    for (let i = 1; i < n; i++) {
        const u = order[i];
        const p = parent[u];
        ans[u] = ans[p] - count[u] + (n - count[u]);
    }

    return Array.from(ans);
};
